package com.aistock.prediction.verification;
import com.fasterxml.jackson.databind.*;import com.aistock.common.BusinessException;
import java.time.*;import java.sql.Timestamp;import java.util.*;
import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;
@Tag("mysql") class VerificationMysqlTest {
 static final Clock NOW=Clock.fixed(Instant.parse("2026-09-23T14:00:00Z"),ZoneOffset.UTC);
 static final ObjectMapper MAPPER=new ObjectMapper().findAndRegisterModules().disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
 static final LocalDate ORIGIN=LocalDate.parse("2026-09-21");
 static final List<LocalDate> TARGETS=List.of("2026-09-22","2026-09-23","2026-09-24","2026-09-25","2026-09-28").stream().map(LocalDate::parse).toList();
 final VerificationDatabaseFixture f=new VerificationDatabaseFixture();
 JsonNode snapshot(){var root=MAPPER.createObjectNode();var input=root.putObject("input");input.put("instrumentId","SH600030").put("originDate",ORIGIN.toString()).put("originRawClose","100");var dates=input.putArray("targetDates");TARGETS.forEach(d->dates.add(d.toString()));var p=root.putObject("prediction");p.put("instrumentId","SH600030").put("originDate",ORIGIN.toString()).put("originRawClose","100").put("formalInference",true).put("validationOnly",false).put("referenceBasis","ORIGIN_SHARE_BASIS");var points=p.putArray("points");for(int i=0;i<5;i++)points.addObject().put("step",i+1).put("targetDate",TARGETS.get(i).toString()).put("referencePrice","105");return root;}
 UUID forecast(String state,boolean hidden){var id=UUID.randomUUID();f.jdbc.update("insert into forecast_request(prediction_id,user_id,operation_id,request_hash,model_id,instrument_id,horizon,state,model_json,snapshot_json,hidden,created_at,expires_at) values(?,?,?,?,?,'SH600030',5,?,'{}',?,?,?,?)",id.toString(),UUID.randomUUID().toString(),UUID.randomUUID().toString(),"a".repeat(64),UUID.randomUUID().toString(),state,state.equals("SUCCEEDED")?snapshot().toString():null,hidden,Timestamp.from(NOW.instant()),Timestamp.from(NOW.instant().plusSeconds(90)));return id;}
 VerificationRequest request(LocalDate due){return new VerificationRequest(UUID.randomUUID(),due,NOW.instant().plusSeconds(90));}
 JsonNode evidence(LocalDate due,String version,String raw){var e=MAPPER.createObjectNode();e.put("realizationVersionId",version).put("instrumentId","SH600030").put("provider","baostock").put("definition","baostock-backward-close-over-raw-v1").put("originDate",ORIGIN.toString()).put("dueThrough",due.toString()).put("rawVersionId","22222222-2222-2222-2222-222222222222").put("rawContentHash","a".repeat(64)).put("sourcePayloadHash","b".repeat(64)).put("calendarHash","c".repeat(64)).put("contentHash","d".repeat(64)).put("capturedAt",NOW.instant().toString()).put("originRawClose","100").put("originBackwardClose","100");var calendar=e.putArray("calendar");for(var d=ORIGIN;!d.isAfter(due.plusDays(5));d=d.plusDays(1))calendar.addObject().put("date",d.toString()).put("open",d.getDayOfWeek().getValue()<6);e.put("calendarHash",VerificationEvidence.hash(MAPPER,calendar));var ds=e.putArray("targetDates");TARGETS.forEach(d->ds.add(d.toString()));var obs=e.putArray("observations");for(var d:TARGETS)if(!d.isAfter(due))obs.addObject().put("date",d.toString()).put("state","VERIFIED").put("rawClose",raw).put("backwardClose",raw);e.put("contentHash",VerificationEvidence.hash(MAPPER,List.of("SH600030","baostock-backward-close-over-raw-v1",ORIGIN,TARGETS,due,"22222222-2222-2222-2222-222222222222","a".repeat(64),"b".repeat(64),e.path("calendarHash").asText(),"100","100",obs)));return e;}
 VerificationService service(VerificationMarketClient client){return new VerificationService(new VerificationRepository(f.jdbc,MAPPER,NOW),client,new VerificationCalculator(),MAPPER,NOW,20);}
 @Test void modifiedCalendarHashIsRejected(){var id=forecast("SUCCEEDED",false);var s=service((r,p)->{var e=evidence(r.dueThrough(),UUID.randomUUID().toString(),"102");((com.fasterxml.jackson.databind.node.ObjectNode)e.path("calendar").get(0)).put("open",false);return e;});assertEquals("FAILED",s.verify(id,request(TARGETS.get(0))).state());assertEquals(0,f.jdbc.queryForObject("select count(*) from forecast_verification_version",Integer.class));}
 @Test void lateOlderOperationCannotRegressSameCutoffHead()throws Exception{var id=forecast("SUCCEEDED",false);var first=request(TARGETS.get(0));var second=request(TARGETS.get(0));var entered=new java.util.concurrent.CountDownLatch(1);var release=new java.util.concurrent.CountDownLatch(1);var s=service((r,p)->{if(r.operationId().equals(first.operationId())){entered.countDown();try{if(!release.await(5,java.util.concurrent.TimeUnit.SECONDS))throw new AssertionError("release timeout");}catch(InterruptedException e){Thread.currentThread().interrupt();throw new IllegalStateException(e);}}return evidence(r.dueThrough(),UUID.randomUUID().toString(),r.operationId().equals(first.operationId())?"101":"103");});var executor=java.util.concurrent.Executors.newSingleThreadExecutor();try{var old=executor.submit(()->s.verify(id,first));assertTrue(entered.await(5,java.util.concurrent.TimeUnit.SECONDS));var latest=s.verify(id,second);release.countDown();assertEquals("AVAILABLE",old.get(5,java.util.concurrent.TimeUnit.SECONDS).state());assertEquals(latest.versionId(),s.current(id).path("verificationVersionId").asText());assertEquals(2,f.jdbc.queryForObject("select count(*) from forecast_verification_version",Integer.class));}finally{release.countDown();executor.shutdownNow();}}
 @Test void totalBudgetPreventsPublishingBeforeLongerLeaseExpires(){var time=new java.util.concurrent.atomic.AtomicReference<Instant>(NOW.instant());Clock advancing=new Clock(){public ZoneId getZone(){return ZoneId.of("Asia/Shanghai");}public Clock withZone(ZoneId z){return this;}public Instant instant(){return time.get();}};var id=forecast("SUCCEEDED",false);var repo=new VerificationRepository(f.jdbc,MAPPER,advancing);var s=new VerificationService(repo,(r,p)->{time.set(NOW.instant().plusSeconds(91));return evidence(r.dueThrough(),UUID.randomUUID().toString(),"102");},new VerificationCalculator(),MAPPER,advancing,20);var r=new VerificationRequest(UUID.randomUUID(),TARGETS.get(0),NOW.instant().plusSeconds(120));var receipt=s.verify(id,r);assertEquals("FAILED",receipt.state());assertEquals("VERIFICATION_BUDGET_EXCEEDED",receipt.errorCode());assertEquals(0,f.jdbc.queryForObject("select count(*) from forecast_verification_version",Integer.class));}
 @Test void abandonedLeaseAndLatePublishCannotChangeExistingResult(){
  var id=forecast("SUCCEEDED",false);var good=service((r,p)->evidence(r.dueThrough(),UUID.randomUUID().toString(),"102"));var prior=good.verify(id,request(TARGETS.get(0)));var repo=new VerificationRepository(f.jdbc,MAPPER,NOW);var r=request(TARGETS.get(1));assertTrue(repo.begin(id,r,"e".repeat(64)).execute());
  var later=new VerificationRepository(f.jdbc,MAPPER,Clock.fixed(NOW.instant().plusSeconds(121),ZoneOffset.UTC));assertEquals("ATTEMPT_EXPIRED",later.operation(r.operationId()).errorCode());assertEquals("FAILED",later.operation(r.operationId()).state());assertEquals(prior.versionId(),later.current(id).path("verificationVersionId").asText());
 }
 @Test void concurrentSameOperationExecutesSourceOnlyOnce()throws Exception{
  var id=forecast("SUCCEEDED",false);var r=request(TARGETS.get(0));var entered=new java.util.concurrent.CountDownLatch(1);var release=new java.util.concurrent.CountDownLatch(1);var calls=new java.util.concurrent.atomic.AtomicInteger();String source=UUID.randomUUID().toString();
  var s=service((req,p)->{calls.incrementAndGet();entered.countDown();try{if(!release.await(5,java.util.concurrent.TimeUnit.SECONDS))throw new AssertionError("release timeout");}catch(InterruptedException e){Thread.currentThread().interrupt();throw new IllegalStateException(e);}return evidence(req.dueThrough(),source,"102");});
  var executor=java.util.concurrent.Executors.newSingleThreadExecutor();try{var first=executor.submit(()->s.verify(id,r));assertTrue(entered.await(5,java.util.concurrent.TimeUnit.SECONDS));assertEquals("RUNNING",s.verify(id,r).state());release.countDown();assertEquals("AVAILABLE",first.get(5,java.util.concurrent.TimeUnit.SECONDS).state());assertEquals(1,calls.get());assertEquals(1,f.jdbc.queryForObject("select count(*) from forecast_verification_version",Integer.class));}finally{release.countDown();executor.shutdownNow();}
 }
 @Test void failurePreservesPriorResultAndSnapshot(){var id=forecast("SUCCEEDED",false);var s=service((r,p)->evidence(r.dueThrough(),UUID.randomUUID().toString(),"102"));var prior=s.verify(id,request(TARGETS.get(0)));var before=f.jdbc.queryForObject("select snapshot_json from forecast_request where prediction_id=?",String.class,id.toString());var fail=service((r,p)->{throw new IllegalStateException("offline");});assertEquals("FAILED",fail.verify(id,request(TARGETS.get(1))).state());assertEquals(prior.versionId(),s.current(id).path("verificationVersionId").asText());assertEquals(before,f.jdbc.queryForObject("select snapshot_json from forecast_request where prediction_id=?",String.class,id.toString()));}
 @Test void appendOnlyReplayAndHiddenForecastNeedNoPublishedModel(){var id=forecast("SUCCEEDED",true);var calls=new java.util.concurrent.atomic.AtomicInteger();String source=UUID.randomUUID().toString();var s=service((r,p)->{calls.incrementAndGet();return evidence(r.dueThrough(),source,"102");});var r=request(TARGETS.get(0));var result=s.verify(id,r);assertEquals("AVAILABLE",result.state());assertEquals(result,s.verify(id,r));assertEquals(1,calls.get());var original=f.jdbc.queryForObject("select snapshot_json from forecast_request where prediction_id=?",String.class,id.toString());assertEquals("PARTIAL",s.current(id).path("result").path("state").asText());var duplicate=s.verify(id,request(TARGETS.get(0)));assertEquals(result.versionId(),duplicate.versionId());assertEquals(1,f.jdbc.queryForObject("select count(*) from forecast_verification_version",Integer.class));assertEquals(original,f.jdbc.queryForObject("select snapshot_json from forecast_request where prediction_id=?",String.class,id.toString()));assertEquals(result,new VerificationRepository(f.jdbc,MAPPER,NOW).operation(r.operationId()));}
 @Test void newEvidenceAppendsAndOlderCutoffCannotRegressHead(){var id=forecast("SUCCEEDED",false);var s=service((r,p)->evidence(r.dueThrough(),UUID.randomUUID().toString(),r.dueThrough().equals(TARGETS.get(1))?"103":"102"));var latest=s.verify(id,request(TARGETS.get(1)));s.verify(id,request(TARGETS.get(0)));assertEquals(latest.versionId(),s.current(id).path("verificationVersionId").asText());assertEquals(2,f.jdbc.queryForObject("select count(*) from forecast_verification_version",Integer.class));}
 @Test void noDueSkipsAndNonSuccessOrChangedOperationReject(){var s=service((r,p)->{throw new AssertionError("must not collect");});var id=forecast("SUCCEEDED",false);var r=request(ORIGIN);assertEquals("SKIPPED_NOT_DUE",s.verify(id,r).state());assertThrows(BusinessException.class,()->s.verify(id,new VerificationRequest(r.operationId(),TARGETS.get(0),r.leaseUntil())));assertThrows(BusinessException.class,()->s.verify(forecast("FAILED",false),request(ORIGIN)));assertEquals(0,f.jdbc.queryForObject("select count(*) from forecast_verification_version",Integer.class));}
 @Test void sourceFailureExpiredAndWrongStockDoNotSaveEvaluation(){var id=forecast("SUCCEEDED",false);var failed=service((r,p)->{throw new BusinessException("VERIFICATION_SOURCE_UNAVAILABLE","unavailable",org.springframework.http.HttpStatus.SERVICE_UNAVAILABLE);});assertEquals("FAILED",failed.verify(id,request(TARGETS.get(0))).state());var bad=service((r,p)->{var e=(com.fasterxml.jackson.databind.node.ObjectNode)evidence(r.dueThrough(),UUID.randomUUID().toString(),"102");return e.put("instrumentId","SZ000002");});assertEquals("FAILED",bad.verify(id,request(TARGETS.get(0))).state());var expired=new VerificationRequest(UUID.randomUUID(),TARGETS.get(0),NOW.instant().minusSeconds(1));assertEquals("ATTEMPT_EXPIRED",failed.verify(id,expired).errorCode());assertEquals(0,f.jdbc.queryForObject("select count(*) from forecast_verification_version",Integer.class));}
}
